const query = $input.first().json.query;
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
if (mode === 'subscribe' && token === 'eventpay-verify') {
  return [{ json: { challenge } }];
}
return [{ json: { error: 'failed' } }];

const body = $input.first().json.body;
try {
  const entry = body.entry[0];
  const changes = entry.changes[0];
  const value = changes.value;
  if (!value.messages || !value.messages.length) {
    return [{ json: { skip: true } }];
  }
  const message = value.messages[0];
  return [{
    json: {
      phone: message.from,
      text: message.text?.body || '',
      wa_phone_number_id: value.metadata.phone_number_id,
      wa_number: value.metadata.display_phone_number || value.metadata.phone_number_id
    }
  }];
} catch(e) {
  return [{ json: { skip: true } }];
}

const data = $input.first().json;
if (!data.phone || data.skip) {
  return [];
}
return [$input.first()];

const phone = $input.first().json.phone;
const text = $input.first().json.text;
const wa_number = $input.first().json.wa_number;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://127.0.0.1:8000/api/v1/n8n/session/message',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': 'eventpay-n8n-secret-2024'
  },
  body: { phone, text, wa_number }
});

return [{ json: { ...response, phone } }];

const data = $input.first().json;
if (data.action !== 'reply' || !data.message) {
  return [];
}

const phone = data.phone;
const message = data.message;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://graph.facebook.com/v18.0/1073260732545641/messages',
  headers: {
    'Authorization': 'Bearer PASTE_YOUR_TOKEN_HERE',
    'Content-Type': 'application/json'
  },
  body: {
    messaging_product: 'whatsapp',
    to: phone,
    type: 'text',
    text: { body: message }
  }
});

return [{ json: response }];

const payload = $input.first().json.body;
const event = payload.event;
let notes = {};
let phone = '';
let amount = 0;

if (event === 'payment_link.paid') {
  const entity = payload.payload.payment_link.entity;
  notes = entity.notes || {};
  phone = entity.customer?.contact || '';
  amount = entity.amount / 100;
} else if (event === 'payment.captured') {
  const entity = payload.payload.payment.entity;
  notes = entity.notes || {};
  phone = entity.contact || '';
  amount = entity.amount / 100;
} else {
  return [];
}

if (!notes.tenant_id) return [];

return [{ json: { tenant_id: notes.tenant_id, event_id: notes.event_id, registration_id: notes.registration_id, phone, amount } }];

const data = $input.first().json;

await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://127.0.0.1:8000/api/v1/n8n/' + data.tenant_id + '/events/' + data.event_id + '/sync-sheet',
  headers: { 'x-api-key': 'eventpay-n8n-secret-2024' }
});

const msg = 'Payment of Rs.' + data.amount + ' received! Your registration is confirmed. Thank you!';

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://graph.facebook.com/v18.0/1073260732545641/messages',
  headers: {
    'Authorization': 'Bearer PASTE_YOUR_TOKEN_HERE',
    'Content-Type': 'application/json'
  },
  body: {
    messaging_product: 'whatsapp',
    to: data.phone,
    type: 'text',
    text: { body: msg }
  }
});

return [{ json: { status: 'ok' } }];
